import {PANELS,BATTERIES,PRICEBOOK} from '/studio-src/catalogue.mjs';
import {uuid,defaults,sanitise,faceGeometry,roofSlots,setPanelCount,reflowPanels,recommendations,HOUSE_TEMPLATES,ROOF_TEMPLATES,mountingZones,cost,energy,advice,money,compass,clamp} from '/studio-src/engine.mjs';
import {PROFILES,TARIFFS} from '/trust/data.mjs';
import {sceneSvg} from '/studio-src/scene.mjs';
const $=s=>document.querySelector(s), STORE='sunward-studio-v4';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let restored;try{restored=JSON.parse(localStorage.getItem(STORE)||localStorage.getItem('sunward-studio-v3')||'null')}catch{}
let design=sanitise(restored?.design||defaults()),property=restored?.property||null,address=String(restored?.address||property?.address||''),step=['home','energy','plans','design','quote'].includes(restored?.step)?restored.step:'home',qIndex=Math.min(5,Math.max(0,Number(restored?.qIndex)||0)),tab='panels',face='front',sceneView='home',camera='front';
let propertyReady=false,providerChecked=false,lookupBusy=false,lookupMessage='',lookupResults=[],propertyConsent=false,quote=null,quoteRevision='',requestNumber=0,revision=0,history=[],resumed=!!restored,savedReceipt=null;
if(restored?.design?.v!==4){design.panels=[];if(restored?.design?.panels?.length)setPanelCount(design,'front',restored.design.panels.length);}
const initialParams=new URLSearchParams(location.search);if(['solar','battery','both'].includes(initialParams.get('goal'))){design.goal=initialParams.get('goal');if(design.goal==='solar'){design.battery='none';design.modules=0;}if(design.goal==='battery')design.panels=[];}
if(initialParams.get('address'))address=initialParams.get('address').slice(0,240);
if(initialParams.get('ev')==='1')design.ev=true;
if(initialParams.get('heatpump')==='1')design.heatpump=true;
if(PANELS.some(p=>p.id===initialParams.get('panel'))){design.panel=initialParams.get('panel');reflowPanels(design);}
if(BATTERIES.some(p=>p.id===initialParams.get('battery'))){design.battery=initialParams.get('battery');design.modules=design.battery==='none'?0:1;}

const battery=()=>BATTERIES.find(b=>b.id===design.battery)||BATTERIES[0],panel=()=>PANELS.find(p=>p.id===design.panel)||PANELS[0];
const round50=n=>Math.round(n/50)*50,number=n=>new Intl.NumberFormat('en-GB').format(n),rMoney=n=>money(round50(n));
function event(name,data={}){window.SunwardGrowth?.event(name,data)}
function save(){try{localStorage.setItem(STORE,JSON.stringify({design,property,address,step,qIndex,updatedAt:new Date().toISOString()}));$('#save-state').textContent='Saved on this device'}catch{$('#save-state').textContent='Device storage unavailable';}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function invalidate(){quote=null;quoteRevision='';savedReceipt=null;revision++;requestNumber++;}
function snapshot(){history.push(JSON.stringify(design));if(history.length>25)history.shift();}
function update(){design=sanitise(design);if(!faceGeometry(design).some(f=>f.id===face))face=faceGeometry(design)[0].id;invalidate();save();render();}
function go(next){step=next;save();render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});event('studio_step_view',{step});if(step==='quote')getQuote();}
function image(p,cls=''){return p.image?`<div class="product-img ${cls}"><img src="${esc(p.image)}" alt="${esc(p.imageNote||p.brand+' '+p.name)}" width="320" height="320" loading="lazy" decoding="async"></div>`:'<div class="blank">Solar only</div>';}
function opt(values,current){return values.map(([v,l])=>`<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}
function field(label,key,type='number',extra=''){return `<label class="field"><span>${label}</span><input data-field="${key}" id="field-${key}" type="${type}" value="${esc(design[key])}" ${extra}></label>`;}
function select(label,key,values){return `<label class="field"><span>${label}</span><select data-field="${key}" id="field-${key}">${opt(values,design[key])}</select></label>`;}
function check(label,key,small=''){return `<label class="check"><input type="checkbox" data-field="${key}" ${design[key]?'checked':''}><span>${label}${small?`<br><small>${small}</small>`:''}</span></label>`;}
function range(label,key,min,max,step,unit=''){return `<label class="field"><span>${label}<output id="out-${key}">${key==='azimuth'?compass(design[key]):design[key]+unit}</output></span><input data-field="${key}" data-unit="${unit}" id="field-${key}" type="range" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${design[key]}"></label>`;}
function head(eyebrow,title,description,action=''){return `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${action}</div>`}
function renderSteps(){const current=step==='plans'?'energy':step;$('#steps').innerHTML=[['home','Your home'],['energy','Your energy'],['design','Your system'],['quote','Your estimate']].map(([s,n],i)=>`<button data-action="go" data-value="${s}" class="${current===s?'active':''} ${['home','energy','design','quote'].indexOf(current)>i?'done':''}" ${current===s?'aria-current="step"':''}><span>${i+1}</span>${n}</button>`).join('');}
function render(){const focused=document.activeElement,activeId=focused?.id,slotId=focused?.dataset?.slot,action=focused?.dataset?.action,actionValue=focused?.dataset?.value,actionKey=focused?.dataset?.key;const openDetails=[...document.querySelectorAll('#app details[open]')].map(x=>x.querySelector('summary')?.textContent);renderSteps();$('#app').innerHTML=step==='home'?home():step==='energy'?quiz():step==='plans'?plans():step==='design'?studio():quotePage();document.querySelectorAll('#app details').forEach(x=>{if(openDetails.includes(x.querySelector('summary')?.textContent))x.open=true});renderMobile();bindImages();const focusTarget=activeId?document.getElementById(activeId):slotId?[...document.querySelectorAll('[data-slot]')].find(x=>x.dataset.slot===slotId):action?[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===action&&x.dataset.value===actionValue&&x.dataset.key===actionKey):null;focusTarget?.focus({preventScroll:true});}
function bindImages(){document.querySelectorAll('.product-img img').forEach(img=>img.addEventListener('error',()=>{img.parentElement.innerHTML='<span class="small">Product image unavailable</span>'},{once:true}));}
function renderMobile(){const show=step==='design',e=energy(design),c=cost(design);$('#mobile-summary').hidden=!show;$('#mobile-summary').innerHTML=show?`<div><small>Indicative installed total</small><strong>${money(c.total)}</strong></div><button class="btn" data-action="go" data-value="quote">See my estimate <span>→</span></button>`:'';}
function homeGeometry(){return `<div class="fields">${select('Roof type','roof',Object.entries(ROOF_TEMPLATES))}${select('Main roof faces','azimuth',[[0,'North'],[45,'North-east'],[90,'East'],[135,'South-east'],[180,'South'],[225,'South-west'],[270,'West'],[315,'North-west']])}${field('Width of your property (m)','width','number','min="3" max="18" step=".1"')}${field('Depth of your property (m)','depth','number','min="3" max="18" step=".1"')}${range('Roof pitch','pitch',5,55,1,'°')}${range('Known shading','shade',0,60,5,'%')}</div><p class="small">Dimensions describe your part of the building. Roof dimensions and usable panel area require confirmation.</p>`;}
function home(){return head('Sunward Studio','Your home. More potential.','A few details. A system that makes sense. Start with your home, then see what solar and storage could do for you.')+
`${resumed?'<div class="resume"><span>Your previous design is here, ready when you are.</span><button class="btn-outline" data-action="resume">Continue design →</button></div>':''}
<div class="home-layout"><div class="home-form"><h2>Where shall we start?</h2><form id="lookup-form"><label class="field"><span>UK address or postcode <small>Optional</small></span><div class="input-action"><input id="addressInput" name="address" autocomplete="street-address" maxlength="240" value="${esc(address)}" placeholder="Your postcode or street address"><button id="lookupBtn" class="btn" type="submit" ${!propertyReady||lookupBusy?'disabled':''}>${lookupBusy?'Finding your home…':'Find my home'}</button></div></label>
${propertyReady?`<label class="check"><input id="property-consent" type="checkbox" ${propertyConsent?'checked':''}><span>Use this address to check roof, EPC and planning records with Searchland</span></label>`:''}
<p class="small muted">${providerChecked?(propertyReady?'Based on available property records. You confirm anything that looks wrong.':'Property records are unavailable in this preview. Choose your home below to keep going.'):'Checking property record availability…'}</p></form>
<div aria-live="polite">${lookupMessage?`<div class="notice">${esc(lookupMessage)}</div>`:''}${lookupResults.map((r,i)=>`<button class="address-result" data-action="property" data-value="${i}">${esc(r.address)}</button>`).join('')}</div>
${property?`<div class="notice"><strong>Based on available property records</strong><br>${esc(property.address)}<br>${property.roofArea?`${Math.round(property.roofArea)} m² recorded roof area · `:''}${esc(property.epc?.rating?'EPC '+property.epc.rating:'EPC not returned')}<br><small>Aggregate building records inform this template. They do not measure usable roof facets.</small></div>`:''}
<div class="subsection"><h3>Which looks most like your home?</h3><div class="house-options">${Object.entries(HOUSE_TEMPLATES).map(([id,t])=>`<button class="option ${design.house===id?'selected':''}" data-action="house" data-value="${id}" aria-pressed="${design.house===id}">${t.name}<span class="option-check">${design.house===id?'✓':''}</span></button>`).join('')}</div></div>
<details class="details"><summary>Roof shape & approximate dimensions</summary>${homeGeometry()}</details><div class="home-bottom"><button class="btn full" data-action="go" data-value="energy">Find my solar potential <span>→</span></button></div><p class="small muted" style="margin-top:12px;text-align:center">Explore freely. No phone number needed.</p></div>
<div class="home-visual"><div class="visual-head"><strong>Your starting point</strong><span>Adjustable house template</span></div><div class="scene" id="home-scene">${sceneSvg(design,face,'home','front')}</div><div class="visual-caption"><div><strong>${HOUSE_TEMPLATES[design.house].name} · ${ROOF_TEMPLATES[design.roof]} roof</strong><br>This model changes with your answers. Your installer confirms the final fit.</div></div><div class="three-facts"><div><strong>Your roof</strong><span>Find a sensible layout</span></div><div><strong>Your energy</strong><span>Size it for your life</span></div><div><strong>Your choice</strong><span>See every allowance</span></div></div></div></div>`;}
const questions=[
 {title:'What would you like to explore?',sub:'Solar, storage or a bit of both. We’ll shape your options around it.',key:'goal',choices:[['both','Solar + battery','Make your own. Save some for later.'],['solar','Solar panels','Start with the potential on your roof.'],['battery','Battery storage','Make better use of your electricity tariff.'],['unsure','Help me decide','Compare the trade-offs together.']],tip:'Start with useful energy.',text:'A bigger system only earns its place if the extra electricity is useful to you or worth exporting. Your roof, usage and tariff work together.'},
 {title:'How much electricity does home use?',sub:'Your latest bill is a good starting point. Include EV and heat-pump use if they are already in your annual total.',key:'usage',tip:'A better starting number.',text:'Your annual electricity use gives us more to work with than the number of bedrooms. If you only know your monthly spend, we can turn that into a rough estimate.'},
 {title:'When does your home need energy?',sub:'Think about appliances, cooking, heating and car charging.',key:'daytime',choices:[['day','Mostly daytime','Someone is usually home during the day.'],['evening','Evenings & overnight','Most electricity use comes after work.']],tip:'Sunshine has a schedule.',text:'Solar generates in daylight. Using it directly avoids battery losses; storage can carry some of it into the evening. Bigger storage is not automatically better.'},
 {title:'What else should we plan around?',sub:'Include what you have now and what is coming next.',key:'loads',tip:'Plan for the whole home.',text:'An EV or heat pump can change your demand significantly. The model uses the annual kWh you entered; it does not quietly add another allowance.'},
 {title:'What matters most to you?',sub:'We’ll use this to explain the choices, so you can decide where to spend.',key:'priority',choices:[['bills','Lower bills','Reduce what you spend on electricity.'],['payback','Value for money','Keep the investment proportionate.'],['independence','Less grid reliance','Use more of your own generation.'],['backup','Power-cut backup','Explore the equipment and checks involved.'],['ev','Charging my car','Plan around a bigger flexible load.'],['generation','More generation','Use the roof’s potential.']],tip:'Backup needs a plan.',text:'Owning a battery does not automatically keep the whole home working during a power cut. Protected circuits, switching equipment and power limits need an installer design.'},
 {title:'A couple of practical details.',sub:'These help us flag the right checks before you invest.',key:'practical',tip:'A good first pass. Then a proper survey.',text:'We’ve done the first-pass planning. Your installer confirms the roof, cable routes, battery siting and grid connection before anything is ordered.'}
];
function quiz(){const q=questions[qIndex];let controls='';
if(q.choices)controls=`<div class="choice-grid">${q.choices.map(([v,l,s])=>`<button class="choice ${design[q.key]===v?'selected':''}" data-action="answer" data-key="${q.key}" data-value="${v}" aria-pressed="${design[q.key]===v}"><strong>${l}</strong><small>${s}</small></button>`).join('')}</div>`;
if(q.key==='usage')controls=`<div class="segmented" style="margin-bottom:24px"><button data-action="usage-mode" data-value="kwh" class="${design.usageMode==='kwh'?'active':''}">I know my kWh</button><button data-action="usage-mode" data-value="spend" class="${design.usageMode==='spend'?'active':''}">I know my monthly spend</button></div>${design.usageMode==='kwh'?field('Annual electricity use (kWh)','annual','number','min="500" max="40000" step="100"'):field('Monthly electricity usage charges (£)','monthlySpend','number','min="15" max="1500" step="5"')}${design.usageMode==='spend'?`<p class="small">Exclude standing charges and gas. At ${design.importP}p/kWh this suggests approximately <strong>${number(round50(design.annual))} kWh/year</strong>. You can update the tariff in Studio.</p>`:''}<div class="notice">Not sure? Keep ${number(design.annual)} kWh as a starting assumption and refine it later.</div>`;
if(q.key==='loads')controls=`${check('EV now or planned','ev')}${check('Heat pump now or planned','heatpump')}${check('I already have solar','existingSolar')}${design.existingSolar?field('Existing solar size (kWp)','existingKwp','number','min="0" max="20" step=".1"'):''}${check('I already have a home battery','existingBattery')}${design.existingSolar?'<div class="notice">Existing solar is estimated separately using a 950 kWh/kWp starting yield. Its actual orientation, inverter and retrofit compatibility need checking.</div>':''}${design.existingBattery?'<div class="notice">We’ll start with no additional battery. Existing storage is excluded from these estimates until its specification is checked.</div>':''}`;
if(q.key==='practical')controls=`${select('Your relationship with the property','owner',[['owner','I own the freehold'],['leaseholder','I am a leaseholder'],['tenant','I rent the property'],['other','Other / shared ownership']])}${range('Approximate shading loss','shade',0,60,5,'%')}${check('There is a garage available','hasGarage')}${check('Power-cut backup is important','backup')}<p class="small">Shading is an annual modelling allowance, not the percentage of roof covered by shade. Your installer will assess it properly.</p>`;
return `<div class="quiz-layout"><section class="quiz-panel"><div class="quiz-meta"><span>${qIndex+1} of ${questions.length}</span><div class="progress"><i style="width:${(qIndex+1)/questions.length*100}%"></i></div><span>Your energy</span></div><h1>${q.title}</h1><p>${q.sub}</p>${controls}<div class="quiz-footer"><button class="text-button" data-action="quiz-back">← Back</button><button class="btn" data-action="quiz-next">${qIndex===questions.length-1?'Show my options':'Continue'} <span>→</span></button></div></section><aside class="education"><div class="education-icon" aria-hidden="true">☼</div><span class="eyebrow">A little solar sense</span><h2>${q.tip}</h2><p>${q.text}</p><a class="source" href="/guides/" target="_blank" rel="noopener">Explore the bright guide ↗</a></aside></div>`;}
function plans(){const options=recommendations(design),insights=advice(design,property).slice(0,2);return head('Your starting options','Three ways to move sunward.','A useful starting point for your home. These are illustrative options, not a claim that one system is optimal. You can change every choice.')+
`<div class="recommend-grid">${options.map(p=>{const b=BATTERIES.find(b=>b.id===p.design.battery),e=p.energy;return `<article class="recommend ${p.id==='better'?'featured':''}"><span class="pill">${p.label}${p.id==='better'?' · Start here':''}</span><h2>${p.title}</h2><p>${p.sub}</p>${image(b.id==='none'?PANELS.find(x=>x.id===p.panel):b)}<div class="plan-price">${money(p.cost.total)}</div><p class="small">Indicative installed total</p><div class="plan-metrics"><div><strong>${p.design.panels.length} panels</strong><small>${e.kwp.toFixed(2)} kWp solar</small></div><div><strong>${number(+e.capacity.toFixed(2))} kWh</strong><small>Usable storage</small></div><div><strong>${rMoney(e.savingsLow)}–${rMoney(e.savingsHigh)}</strong><small>Illustrative benefit / year</small></div><div><strong>${b.id==='none'?'Solar only':b.brand}</strong><small>${b.id==='none'?'No new battery':b.name}${b.id.startsWith('sigen')?' · representative stack shown':''}</small></div></div><button class="${p.id==='better'?'btn':'btn-outline'}" data-action="plan" data-value="${p.id}">Make this mine <span>→</span></button></article>`}).join('')}</div>
<div class="advice-strip">${insights.map(a=>`<div><strong>${esc(a.title)}</strong><p>${esc(a.text)}</p></div>`).join('')}</div><p class="small">Starting assumptions: ${number(design.annual)} kWh annual use · ${design.importP}p import · ${design.exportP}p export · ${design.shade}% shading. Savings ranges are a sensitivity illustration, not a guarantee. Export income is included. No grant, finance or tariff offer is assumed.</p><div class="quiz-footer"><button class="text-button" data-action="go" data-value="energy">← Change my answers</button><button class="btn-outline" data-action="go" data-value="design">Build from my own choices →</button></div>`;}
function summary(onQuote=false){const e=quote?.energy||energy(design),c=quote?.cost||cost(design);return `<aside class="summary"><span class="eyebrow">Your energy, in view</span><h2>${e.kwp.toFixed(2)} kWp solar</h2><p>${design.panels.length} new panels · ${number(+e.capacity.toFixed(2))} kWh usable storage</p><div class="summary-metrics"><div><span>Estimated generation</span><strong>${number(round50(e.generationLow))}–${number(round50(e.generationHigh))}<br>kWh / year</strong></div><div><span>Annual energy benefit</span><strong>${rMoney(e.savingsLow)}–${rMoney(e.savingsHigh)}</strong></div><div><span>Solar used by your home</span><strong>${Math.round(e.solarFraction)}% of demand</strong></div></div><div class="energy-bar" aria-label="Solar supplies ${Math.round(e.solarFraction)} percent of annual use"><i style="width:${e.solarFraction}%"></i></div><p>Includes export income. Based on your assumptions.</p><div class="summary-price"><span>Indicative installed total</span><strong>${money(c.total)}</strong><p>Illustrative allowances. Confirmed pricing follows a survey.</p></div>${onQuote?`<div class="next-actions"><button class="btn-light" data-action="download">Save my estimate <span>↓</span></button><button class="btn-outline" data-action="email">Email my estimate</button><button class="btn-outline" data-action="survey">Book a survey</button><button class="btn-outline" data-action="accept">Preview quote acceptance</button><button class="text-button" style="color:#e2ecd9" data-action="print">Print / save PDF</button></div><p class="summary-note">Preview actions create no order, booking or payment obligation.</p>`:`<button class="btn-light full" data-action="go" data-value="quote">See my estimate <span>→</span></button><p class="summary-note">No details needed to see the numbers</p>`}</aside>`;}
function panelControls(){const f=faceGeometry(design).find(f=>f.id===face),slots=roofSlots(design,face),n=design.panels.filter(p=>p.face===face).length;return `<div class="panel-fields"><div>${select('Panel model','panel',PANELS.map(p=>[p.id,`${p.brand} · ${p.watts}W`]))}<div class="panel-product">${image(panel())}<p class="small">${esc(panel().name)}<br>Manufacturer module artwork</p></div><div class="spec-grid"><div><span>Exact model</span><b>${esc(panel().model)}</b></div><div><span>Module size</span><b>${panel().length*1000} × ${panel().width*1000} mm</b></div><div><span>Product / performance warranty</span><b>${esc(panel().warranty||'See manufacturer terms')}</b></div><div><span>Manufacturer data</span><a href="${esc(panel().source)}" target="_blank" rel="noopener">View specification ↗</a></div></div></div><div>${select('Panel orientation','orientation',[['portrait','Portrait'],['landscape','Landscape']])}<label class="field"><span>Panels on ${esc(f.label)}<small>${slots.length} slots available</small></span><div class="count-control"><button data-action="count" data-value="-1" aria-label="Remove one panel" ${n<=0?'disabled':''}>−</button><input id="panel-count" aria-label="Number of panels on selected roof" type="number" min="0" max="${slots.length}" value="${n}"><button data-action="count" data-value="1" aria-label="Add one panel" ${n>=slots.length?'disabled':''}>+</button></div></label><div class="inline-actions"><button class="btn-outline" data-action="fill">Fill this roof</button><button class="text-button" data-action="clear">Clear this roof</button><button class="text-button" data-action="undo" ${history.length?'':'disabled'}>Undo</button></div></div></div><div class="notice">${design.goal==='battery'?'You started with battery storage. Adding roof panels will also include a solar installation in your estimate.':'Tap “Roof plan” above to add or remove individual panels. Every slot respects the current edge allowance and roof shape.'}</div><details class="details"><summary>Roof & keep-clear settings</summary>${homeGeometry()}${select('Edge allowance','setback',[[.4,'40 cm'],[.5,'50 cm'],[.6,'60 cm'],[.8,'80 cm']])}<label class="field"><span>Central keep-clear area</span><select id="obstruction">${opt([['none','None known'],['skylight','Skylight · 1 × 1.2 m'],['chimney','Chimney · 1 × 1 m']],design.obstacles.length?'skylight':'none')}</select></label><p class="small">This fixed obstruction allowance is a starting point. Installer-measured positions and clearances replace it at survey.</p></details>`;}
function batteryControls(){const b=battery(),zone=mountingZones(design).find(z=>z.id===design.batteryZone)||mountingZones(design)[0];return `<div class="hardware-grid">${BATTERIES.filter(b=>b.id!=='none').map(b=>`<button class="hardware ${b.id===design.battery?'selected':''}" data-action="battery" data-value="${b.id}" aria-pressed="${b.id===design.battery}">${image(b)}<strong>${esc(b.name)}</strong><span>${b.usable} kWh usable${b.id.startsWith('sigen')?' · system shown':''}</span></button>`).join('')}</div><div class="selected-product"><div><span class="eyebrow">${esc(b.brand)}</span><h3>${esc(b.name)}</h3></div><button class="text-button" data-action="battery" data-value="none">Solar only</button></div>${b.id!=='none'?`<div class="spec-grid"><div><span>Nominal / usable energy</span><b>${b.nominal??'Not published'} / ${b.usable} kWh per unit</b></div><div><span>H × W × D</span><b>${Math.round(b.height*1000)} × ${Math.round(b.width*1000)} × ${Math.round(b.depth*1000)} mm</b></div><div><span>Warranty</span><b>${esc(b.warranty||'10 years · terms apply')}</b></div><div><span>Product documentation</span><a href="${esc(b.source)}" target="_blank" rel="noopener">Manufacturer specification ↗</a></div></div><div class="panel-fields">${field(b.id.startsWith('sigen')?'Battery modules':'Battery units','modules','number',`min="1" max="${b.max}" step="1"`)}${select('Candidate installation zone','batteryZone',mountingZones(design).map(z=>[z.id,z.name]))}</div><div class="mount-detail">${image(b)}<div><span class="pill">${esc(zone.name)}</span><h3>${design.modules} × ${esc(b.name)}</h3><p>${esc(zone.note)}</p><small>${esc(b.id.startsWith('sigen')?'Representative SigenStor stack shown. Module dimensions exclude controller, covers and base.':'Manufacturer product image. Installation clearances are additional to product dimensions.')}</small></div></div>${check('Include a backup equipment allowance','backup')}<p class="small muted">${esc(b.controller||'Compatible system equipment is included as an allowance.')} Battery siting is a candidate choice until an installer checks the manufacturer instructions and the property.</p>`:'<p>No additional battery in this system. You can still use solar during the day and export the surplus.</p>'}`;}
function tariffContext(){const key=design.ev?'ev':design.heatpump?'heat':design.goal==='battery'&&!design.existingSolar?'battery':design.battery==='none'?'solar':'both',p=PROFILES[key];const options=p.shortlist.slice(0,2).map(id=>TARIFFS.find(t=>t.id===id));return `<section class="tariff-context"><span class="eyebrow">TARIFFS THAT MAY FIT</span><h3>${esc(p.title)}</h3><p>${esc(p.caution)}</p><div>${options.map(t=>`<a href="${t.source}" target="_blank" rel="noopener noreferrer"><span>${esc(t.supplier+' · '+t.name)}</span><strong>${esc(t.headline)} <small>${esc(t.unit)}</small></strong><span>${esc(t.scope)}</span></a>`).join('')}</div><p class="small">Official pages checked 7 September 2026. These references do not change your model inputs. Check eligibility and enter your own quoted rates above.</p><a href="/tariffs/?setup=${key}" target="_blank" rel="noopener noreferrer">Compare the setup guidance & whole bill ↗</a></section>`;}
function usageControls(){return `<div class="fields">${field('Annual electricity use (kWh)','annual','number','min="500" max="40000" step="100"')}${select('Main usage pattern','daytime',[['day','Mostly daytime'],['evening','Evenings & overnight']])}${field('Import electricity (p/kWh)','importP','number','min="1" max="100" step=".1"')}${field('Export payment (p/kWh)','exportP','number','min="0" max="100" step=".1"')}${field('Off-peak electricity (p/kWh)','offpeakP','number','min="0" max="100" step=".1"')}${range('Shading allowance','shade',0,60,5,'%')}</div>${check('EV now or planned','ev')}${check('Heat pump now or planned','heatpump')}${check('Bird protection allowance','bird')}<div class="notice">These are editable tariff assumptions, not current tariff offers. Off-peak shifting is modelled only for a system without solar generation. Annual usage should already include your EV or heat pump.</div>${tariffContext()}`;}
function studio(){return head('Your system','Make it feel like yours.','A guided layout. Real hardware. Your numbers, as you go.',`<button class="btn-outline" data-action="go" data-value="plans">Compare options</button>`)+`<div class="studio-layout"><div><div class="workspace-card"><div class="studio-head"><strong>${HOUSE_TEMPLATES[design.house].name} · ${ROOF_TEMPLATES[design.roof]}</strong><div class="segmented"><button class="${sceneView==='home'?'active':''}" data-action="scene" data-value="home">Home view</button><button class="${sceneView==='plan'?'active':''}" data-action="scene" data-value="plan">Roof plan</button></div></div><div class="scene" id="design-scene">${sceneSvg(design,face,sceneView,camera)}</div><div class="face-tabs">${faceGeometry(design).map(f=>`<button class="${f.id===face?'active':''}" data-action="face" data-value="${f.id}">${f.label} · ${compass(f.azimuth)} <strong>${design.panels.filter(p=>p.face===f.id).length}</strong></button>`).join('')}</div><div class="scene-foot"><span>${design.panels.length} panels · ${energy(design).kwp.toFixed(2)} kWp${design.battery!=='none'?' · '+mountingZones(design).find(z=>z.id===design.batteryZone)?.name:''}</span>${sceneView==='home'?`<button class="text-button" data-action="camera">${camera==='front'?'View from rear':'View from front'} ↻</button>`:'<span>Tap + or − to edit</span>'}</div></div><section class="studio-panel"><div class="tab-row" role="tablist" aria-label="System controls">${[['panels','Solar panels'],['battery','Battery storage'],['usage','Energy & tariff']].map(([v,t])=>`<button role="tab" aria-selected="${tab===v}" data-action="tab" data-value="${v}" class="${tab===v?'active':''}">${t}</button>`).join('')}</div>${tab==='panels'?panelControls():tab==='battery'?batteryControls():usageControls()}</section><p class="education-line"><strong>${tab==='panels'?'A little roof sense.':tab==='battery'?'Storage that earns its space.':'Numbers with context.'}</strong> ${tab==='panels'?(design.roof==='flat'?'Flat roofs need mounting tilt and extra row spacing. The grid reserves 60 cm between rows; an installer confirms ballast, wind loading and self-shading.':'South-facing roofs usually maximise annual output. East/west layouts can spread generation across more of your day.'):tab==='battery'?'Storage should be compared with your overnight consumption and tariff. The zone marker is a candidate location; the product is shown separately so no model can pass through a wall or roof.':'A simple monthly energy balance illustrates the trade-offs. It is not an hourly simulation, a site yield report or a guaranteed return.'}</p></div><div id="summary-host">${summary()}</div></div>`;}
function quotePage(){const e=quote?.energy||energy(design),c=quote?.cost||cost(design);return head('Your Sunward estimate','Your system. Every number.','Here’s the first-pass picture. Take it away, compare your options and come back when you’re ready.',`<button class="btn-outline" data-action="go" data-value="design">← Edit system</button>`)+`<div class="quote-layout"><div><section class="quote-card"><div class="quote-head"><div><span class="eyebrow">Non-binding estimate</span><h2>${e.kwp.toFixed(2)} kWp solar + ${number(+e.capacity.toFixed(2))} kWh storage</h2><p>${esc(address||'Your home · address not supplied')}</p><p class="small" id="quote-status">${quote?'Estimate reference '+esc(quote.id):'Illustrative estimate · checking server pricing…'}</p></div><span class="brand">sunward.</span></div><div class="metrics-four"><div><strong>${design.panels.length}</strong><span>New solar panels</span></div><div><strong>${number(round50(e.annual))}</strong><span>Central generation estimate · kWh/yr</span></div><div><strong>${Math.round(e.solarFraction)}%</strong><span>Annual demand met by solar</span></div><div><strong>${rMoney(e.savings)}</strong><span>Central annual benefit, incl. export</span></div></div></section><section class="quote-card"><h2>Where your investment goes.</h2>${c.items.length?`<table><thead><tr><th>System & installation allowances</th><th>Qty</th><th>Amount</th></tr></thead><tbody>${c.items.map(i=>`<tr><td>${esc(i.label)}${i.qty>1?`<small>${money(i.unit)} per unit</small>`:''}</td><td>${i.qty}</td><td>${money(i.amount)}</td></tr>`).join('')}</tbody></table><div class="total-row"><span>Indicative installed total</span><strong>${money(c.total)}</strong></div><p class="small muted" style="margin-top:15px">${esc(PRICEBOOK.vatNote)} These allowances are not an approved commercial pricebook.</p>`:'<div class="notice">Add panels or a battery to build an itemised estimate.</div><button class="btn" data-action="go" data-value="design">Build my system →</button>'}</section><section class="quote-card"><h2>A year in your energy.</h2><p>Illustrative monthly generation. Summer surplus cannot be stored for winter by a home battery.</p><div class="monthly-chart" role="img" aria-label="Illustrative monthly solar generation, highest during summer">${e.monthly.map((m,i)=>`<div title="${['January','February','March','April','May','June','July','August','September','October','November','December'][i]}: ${Math.round(m.generation)} kWh"><i style="height:${m.generation/Math.max(1,...e.monthly.map(m=>m.generation))*100}%"></i><small>${['J','F','M','A','M','J','J','A','S','O','N','D'][i]}</small></div>`).join('')}</div><div class="assumptions-list"><div><span>Solar used directly</span><strong>${number(round50(e.direct))} kWh</strong></div><div><span>Solar through battery</span><strong>${number(round50(e.stored))} kWh</strong></div><div><span>Estimated export</span><strong>${number(round50(e.exported))} kWh</strong></div><div><span>Solar self-consumption</span><strong>${e.annual?Math.round((e.direct+e.charge)/e.annual*100):0}%</strong></div><div><span>Export income included</span><strong>${rMoney(e.exported*design.exportP/100)}/yr</strong></div><div><span>Battery tariff benefit</span><strong>${rMoney(e.arbitrage)}/yr</strong></div></div></section><section class="quote-card"><h2>What we’ve assumed.</h2><div class="assumptions-list"><div><span>Annual use</span><strong>${number(design.annual)} kWh</strong></div><div><span>Import / export</span><strong>${design.importP}p / ${design.exportP}p</strong></div><div><span>Starting south-facing yield</span><strong>950 kWh/kWp</strong></div><div><span>Battery round-trip efficiency</span><strong>90%</strong></div><div><span>Shading allowance</span><strong>${design.shade}%</strong></div><div><span>Existing solar</span><strong>${design.existingKwp} kWp</strong></div></div><div class="notice">Generation range: ±15%. Annual benefit range: ±20%. These illustrate sensitivity around simple assumptions, not statistical confidence. No inflation, finance charges, maintenance, degradation or equipment replacement costs are included.</div><button class="text-button" data-action="edit-assumptions">Edit these assumptions →</button></section><section class="quote-card"><h2>The final checks are in good hands.</h2><p>We’ve done the first-pass work. Your installer confirms the engineering before anything is ordered.</p><ul class="survey-checks"><li>Usable roof area, structure, wind loading and mounting</li><li>Shading, roof obstacles and electrical strings</li><li>Battery location, clearances, fire safety and cable routes</li><li>Inverter compatibility, earthing and any backup circuits</li><li>Grid connection and relevant property permissions</li></ul>${advice(design,property).filter(a=>a.level==='check').slice(0,3).map(a=>`<div class="notice"><strong>${esc(a.title)}</strong><br>${esc(a.text)}</div>`).join('')}</section></div>${summary(true)}</div>`;}
async function getQuote(){const seq=++requestNumber,current=revision;try{const r=await fetch('/api/studio-quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'quote',design,project:{address}}),signal:AbortSignal.timeout(15000)}),j=await r.json();if(seq!==requestNumber||current!==revision)return;if(!r.ok||!j.quote)throw Error(j.message||'Unable to issue estimate');quote=j.quote;quoteRevision=JSON.stringify(design);if(step==='quote')render();return quote;}catch(e){if(seq===requestNumber&&$('#quote-status'))$('#quote-status').textContent='Illustrative local estimate · server reference unavailable';return null;}}
async function checkProvider(){try{const r=await fetch('/api/studio-property',{cache:'no-store',signal:AbortSignal.timeout(7000)});const j=await r.json();propertyReady=r.ok&&j.ready===true;}catch{propertyReady=false}providerChecked=true;if(step==='home')render();}
async function lookup(){address=$('#addressInput').value.trim();if(!propertyReady)return;propertyConsent=$('#property-consent')?.checked===true;if(!propertyConsent)return toast('Tick the property records consent box to continue');if(address.length<4)return toast('Enter a full postcode or address');lookupBusy=true;lookupMessage='';lookupResults=[];save();render();try{const r=await fetch('/api/studio-property',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'lookup',address,consent:true}),signal:AbortSignal.timeout(45000)}),j=await r.json();if(!r.ok)throw Error(j.message);lookupResults=j.results||[];if(!lookupResults.length)lookupMessage='No exact match returned. Your manual design is still available below.';}catch(e){lookupMessage=e.message||'Property records are unavailable. Continue with your own details.'}finally{lookupBusy=false;render();}}
async function loadProperty(i){const p=lookupResults[i];if(!p)return;lookupMessage='Checking the available roof and EPC records…';lookupResults=[];render();try{const r=await fetch('/api/studio-property',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'property',uprn:p.uprn,consent:true}),signal:AbortSignal.timeout(55000)}),j=await r.json();if(!r.ok)throw Error(j.message);property=j.property;address=property.address||p.address;applyProperty();lookupMessage='Property records added. Confirm the template and dimensions below.';event('property_records_loaded');}catch(e){lookupMessage=e.message||'We couldn’t retrieve roof records. Use your own details below.'}update();}
function applyProperty(){const p=property;if(!p)return;const form=(p.epc?.builtForm||'').toLowerCase(),type=(p.epc?.propertyType||'').toLowerCase();design.house=type.includes('bungalow')?'bungalow':form.includes('semi')?'semi':form.includes('terrace')?'terrace':'detached';Object.assign(design,HOUSE_TEMPLATES[design.house]);const roof=String(p.roofShape||'').toLowerCase();design.roof=roof.includes('flat')?'flat':roof.includes('hip')?'hip':roof.includes('mono')?'mono':'gable';if(p.roofArea&&p.addressCount<=1){const footprint=p.roofArea*(design.roof==='flat'?1:Math.cos(design.pitch*Math.PI/180));design.width=clamp(Math.sqrt(footprint*1.1),3,18);design.depth=clamp(footprint/design.width,3,18);}const az={north:0,north_east:45,east:90,south_east:135,south:180,south_west:225,west:270,north_west:315};const best=Object.entries(p.orientationAreas||{}).filter(([k,n])=>az[k]!==undefined&&n>0).sort((a,b)=>b[1]-a[1])[0];if(best)design.azimuth=az[best[0]];design.panels=[];}
function applyField(el){const key=el.dataset.field;if(!key)return;const before=design[key];snapshot();design[key]=el.type==='checkbox'?el.checked:el.type==='number'||el.type==='range'||['azimuth','setback'].includes(key)?+el.value:el.value;if(before===design[key])return;if(key==='monthlySpend'||(key==='importP'&&design.usageMode==='spend'))design.annual=Math.round(design.monthlySpend*12/(design.importP/100));if(['roof','width','depth','pitch','orientation','panel','setback'].includes(key)){design=sanitise(design);reflowPanels(design);}if(key==='backup'&&design.backup)design.priority='backup';update();}
function toggleSlot(id){const p=roofSlots(design,face).find(p=>p.id===id);if(!p)return;snapshot();const found=design.panels.find(q=>q.face===p.face&&Math.abs(q.x-p.x)<.01&&Math.abs(q.y-p.y)<.01);if(found)design.panels=design.panels.filter(q=>q!==found);else design.panels.push(p);update();event('panel_slot_toggle',{face,panels:design.panels.length});}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function hasSystem(){if(!cost(design).items.length){toast('Add panels or a battery first');return false}return true}
async function ensureQuote(){if(!hasSystem())return null;if(!quote||quoteRevision!==JSON.stringify(design))await getQuote();return quote;}
function estimateText(){const e=energy(design),c=cost(design);return `Sunward — non-binding system estimate\n${address||'Property address not supplied'}\n${quote?'Reference: '+quote.id+'\n':''}${design.panels.length} × ${panel().brand} ${panel().watts}W panels (${e.kwp.toFixed(2)} kWp)\n${design.modules} × ${battery().name} (${number(+e.capacity.toFixed(2))} kWh usable)\nCandidate battery zone: ${mountingZones(design).find(z=>z.id===design.batteryZone)?.name||'None'}\n\n${c.items.map(i=>`${i.qty} × ${i.label}: ${money(i.amount)}`).join('\n')}\nIndicative total: ${money(c.total)}\n\nGeneration: ${number(round50(e.generationLow))}–${number(round50(e.generationHigh))} kWh/year\nIllustrative annual benefit: ${rMoney(e.savingsLow)}–${rMoney(e.savingsHigh)} (includes export)\nAnnual use: ${design.annual} kWh. Import ${design.importP}p; export ${design.exportP}p; off-peak ${design.offpeakP}p. Shading ${design.shade}%. Yield baseline 950 kWh/kWp; 90% battery efficiency.\n\nIllustrative pricing only. No order, booking or payment obligation. Survey, confirmed pricing and written terms required. No finance, maintenance, degradation or replacement costs modelled.\n${PRICEBOOK.vatNote}\n\nReturn to Sunward: ${location.origin}/studio/`;}
async function download(){if(!hasSystem())return;await ensureQuote();const html=`<!doctype html><html lang="en-GB"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Sunward system estimate</title><style>body{font:16px/1.6 Arial;color:#203d30;max-width:780px;margin:50px auto;padding:0 24px}h1{font-size:36px}pre{font:inherit;white-space:pre-wrap}button{padding:12px 20px}@media print{button{display:none}}</style><h1>sunward.</h1><h2>Your system estimate</h2><pre>${esc(estimateText())}</pre></html>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html'}));const a=document.createElement('a');a.href=url;a.download='sunward-estimate.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your non-binding estimate is ready to save');event('estimate_download');}
function email(){if(!hasSystem())return;modal('<h2 id="modal-title">Your estimate, in your inbox.</h2><p>This opens a draft in your email app. You choose when to send it.</p><form id="email-form"><label class="field"><span>Email address</span><input id="email-to" type="email" autocomplete="email" required placeholder="you@example.com" maxlength="180"></label><button class="btn full" type="submit">Open email draft →</button><p class="small muted" style="margin-top:15px">No email is sent automatically. You can also save the estimate as a file.</p></form>');}
function survey(){if(!hasSystem())return;modal('<span class="eyebrow">Survey request preview</span><h2 id="modal-title">Let’s check the real-world fit.</h2><p>Choose a preferred day to preview the next step. This saves a request on this device; no appointment is booked or sent to an installer.</p><form id="survey-form"><label class="field"><span>Preferred survey day</span><input id="survey-date" type="date" min="'+new Date().toISOString().slice(0,10)+'" required></label><label class="field"><span>Preferred time</span><select id="survey-time"><option>Morning</option><option>Afternoon</option><option>Either</option></select></label><button class="btn full" type="submit">Save preview request</button></form>');}
async function accept(){if(!hasSystem())return;const q=await ensureQuote();if(!q){toast('A current server estimate is needed to preview acceptance. Please retry.');return}const current=revision;modal(`<span class="eyebrow">Non-binding preview</span><h2 id="modal-title">Review your next step.</h2><p>${money(q.cost.total)} indicative total. This demonstrates quote acceptance without placing an order.</p><form id="accept-form" data-revision="${current}"><label class="field"><span>Your name</span><input id="accept-name" autocomplete="name" minlength="2" maxlength="100" required></label><label class="check"><input id="accept-scope" type="checkbox" required><span>I have reviewed the selected system and its illustrative price</span></label><label class="check"><input id="accept-preview" type="checkbox" required><span>I understand this is a preview, with no order, payment or installation reservation</span></label><button class="btn full" type="submit">Confirm preview only</button></form>`);}
document.addEventListener('click',async e=>{const slot=e.target.closest('[data-slot]');if(slot){toggleSlot(slot.dataset.slot);return}const roof=e.target.closest('[data-face]');if(roof){face=roof.dataset.face;sceneView='plan';render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value;
if(a==='go')return go(v);if(a==='close-modal')return closeModal();
if(a==='reset'){modal('<h2 id="modal-title">Start a fresh design?</h2><p>This replaces the design saved on this device. Download your current estimate first if you want to keep it.</p><div class="inline-actions"><button class="btn" data-action="confirm-reset">Start again</button><button class="btn-outline" data-action="close-modal">Keep my design</button></div>');return}
if(a==='confirm-reset'){design=defaults();property=null;address='';resumed=false;qIndex=0;invalidate();closeModal();go('home');return}
if(a==='resume'){resumed=false;return go('design')}
if(a==='house'){snapshot();design.house=v;Object.assign(design,HOUSE_TEMPLATES[v]);design.panels=[];update();return}
if(a==='answer'){const key=b.dataset.key;design[key]=v;if(key==='priority')design.backup=v==='backup';if(key==='goal'&&v==='solar'){design.battery='none';design.modules=0}if(key==='goal'&&v==='battery')design.panels=[];update();return}
if(a==='usage-mode'){design.usageMode=v;if(v==='spend')design.annual=Math.round(design.monthlySpend*12/(design.importP/100));update();return}
if(a==='quiz-back'){if(qIndex===0)return go('home');qIndex--;save();render();return}
if(a==='quiz-next'){if(qIndex<questions.length-1){qIndex++;save();render();window.scrollTo({top:0,behavior:'instant'});}else go('plans');return}
if(a==='plan'){const p=recommendations(design).find(p=>p.id===v);design=p.design;invalidate();event('recommendation_selected',{plan:v});return go('design')}
if(a==='scene'){sceneView=v;render();return}if(a==='camera'){camera=camera==='front'?'rear':'front';render();return}
if(a==='face'){face=v;camera=['rear','west'].includes(face)?'rear':'front';render();return}
if(a==='tab'){tab=v;render();return}if(a==='edit-assumptions'){tab='usage';return go('design')}
if(a==='battery'){snapshot();design.battery=v;design.modules=v==='none'?0:Math.max(1,Math.min(design.modules,BATTERIES.find(b=>b.id===v).max));if(design.house==='terrace')camera='rear';update();return}
if(a==='count'||a==='fill'||a==='clear'){snapshot();const n=design.panels.filter(p=>p.face===face).length;setPanelCount(design,face,a==='fill'?100:a==='clear'?0:n+Number(v));update();return}
if(a==='undo'){if(history.length){design=sanitise(JSON.parse(history.pop()));update()}return}
if(a==='property')return loadProperty(Number(v));if(a==='download')return download();if(a==='email')return email();if(a==='survey')return survey();if(a==='accept')return accept();if(a==='print'){if(hasSystem())window.print();}
});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-slot]')&&['Enter',' '].includes(e.key)){e.preventDefault();toggleSlot(e.target.dataset.slot)}});
document.addEventListener('input',e=>{if(e.target.id==='addressInput'){address=e.target.value.slice(0,240);property=null;invalidate();save();}if(e.target.type==='range'&&e.target.dataset.field){const k=e.target.dataset.field,o=$('#out-'+k);if(o)o.textContent=k==='azimuth'?compass(+e.target.value):e.target.value+(e.target.dataset.unit||'');}});
document.addEventListener('change',e=>{if(e.target.id==='property-consent'){propertyConsent=e.target.checked;return}if(e.target.dataset.field)return applyField(e.target);if(e.target.id==='panel-count'){snapshot();setPanelCount(design,face,+e.target.value);update()}if(e.target.id==='obstruction'){snapshot();const f=faceGeometry(design).find(x=>x.id===face);design.obstacles=e.target.value==='none'?[]:[{id:'central',face,x:f.width/2-.5,y:f.length/2-.6,w:1,h:e.target.value==='chimney'?1:1.2}];reflowPanels(design);update();}});
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='lookup-form')return lookup();if(e.target.id==='email-form'){const email=$('#email-to').value.trim();location.href='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent('Your Sunward system estimate')+'&body='+encodeURIComponent(estimateText());closeModal();toast('Email draft opened. Send it from your email app.');return}if(e.target.id==='survey-form'){const date=$('#survey-date').value,time=$('#survey-time').value;try{localStorage.setItem('sunward-survey-preview',JSON.stringify({date,time,design,createdAt:new Date().toISOString()}));$('#modal-body').innerHTML=`<h2 id="modal-title">Preview request saved.</h2><p>${esc(new Date(date+'T12:00:00').toLocaleDateString('en-GB',{dateStyle:'long'}))} · ${esc(time)}</p><div class="notice">Saved on this device only. No appointment is booked and no installer has been contacted.</div><button class="btn full" data-action="close-modal">Back to my estimate</button>`}catch{toast('Your device could not save the request. No booking was made.')}return}if(e.target.id==='accept-form'){if(Number(e.target.dataset.revision)!==revision||!quote||quoteRevision!==JSON.stringify(design)){closeModal();toast('Your design changed. Review a fresh estimate before continuing.');return}savedReceipt={id:'SW-PREVIEW-'+uuid(),estimateId:quote.id,name:$('#accept-name').value.trim(),createdAt:new Date().toISOString(),total:quote.cost.total,binding:false};try{localStorage.setItem('sunward-acceptance-preview',JSON.stringify(savedReceipt));$('#modal-body').innerHTML=`<span class="eyebrow">Preview complete</span><h2 id="modal-title">Your decision, captured.</h2><p>This demonstration is saved on your device.</p><div class="notice"><strong>No order has been placed.</strong><br>No payment, booking or installation obligation was created.</div><p class="small">Reference: ${esc(savedReceipt.id)}</p><button class="btn full" data-action="close-modal">Back to my estimate</button>`}catch{toast('The preview could not be saved. No order was placed.')}}});
render();save();checkProvider();if(step==='quote')getQuote();
